package com.dev.rotinassim

import android.content.Intent
import android.os.Bundle
import android.util.Log
import androidx.activity.enableEdgeToEdge
import androidx.appcompat.app.AppCompatActivity
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat
import androidx.fragment.app.Fragment
import androidx.lifecycle.lifecycleScope
import com.dev.rotinassim.api.RetrofitInstance
import com.dev.rotinassim.api.models.Task
import com.dev.rotinassim.databinding.ActivityPaginaPrincipalBinding
import com.dev.rotinassim.room.DatabaseRoom
import com.dev.rotinassim.room.entities.TaskLocal
import com.dev.rotinassim.utils.CacheUtils
import com.dev.rotinassim.utils.PrefsUtils
import com.google.android.material.dialog.MaterialAlertDialogBuilder
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import retrofit2.Call
import retrofit2.Callback
import retrofit2.Response

class PaginaPrincipal : AppCompatActivity() {

    lateinit var binding: ActivityPaginaPrincipalBinding
    lateinit var userId: String

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        binding = ActivityPaginaPrincipalBinding.inflate(layoutInflater)
        setContentView(binding.root)
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main)) { v, insets ->
            val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom)
            insets
        }
        userId = PrefsUtils.getUserId(applicationContext)
        sincronizarTarefas()
        var telaAtual = R.id.nav_tasks
        alternarTela(TarefasFragment())
        binding.bottomNavigation.setOnItemSelectedListener { item ->
            when (item.itemId) {
                R.id.nav_logoff -> { sair(telaAtual); false }
                R.id.nav_tasks -> {
                    if (telaAtual != R.id.nav_tasks) { alternarTela(TarefasFragment()); telaAtual = R.id.nav_tasks }
                    true
                }
                R.id.nav_settings -> {
                    if (telaAtual != R.id.nav_settings) { alternarTela(ConfiguracaoFragment()); telaAtual = R.id.nav_settings }
                    true
                }
                else -> false
            }
        }
    }

    fun sincronizarTarefas() {
        if (userId.isBlank()) { Log.d("Sync", "UserId vazio, cancelando sync"); return }
        lifecycleScope.launch {
            try {
                val db = DatabaseRoom.getDatabase(applicationContext)
                val dao = db.taskLocalDao()
                lifecycleScope.launch {
                    val tasksLocais = withContext(Dispatchers.IO) { dao.buscarTarefasPorUsuarioTodas(userId) }
                    val tasksApi = tasksLocais.map { it.toApi() }
                    RetrofitInstance.INSTANCE.sincronizar(userId, tasksApi)
                        .enqueue(object : Callback<List<Task>> {
                            override fun onResponse(call: Call<List<Task>>, response: Response<List<Task>>) {
                                if (!response.isSuccessful) {
                                    return
                                }
                                val lista = response.body().orEmpty()
                                lifecycleScope.launch{
                                    lista.forEach { t ->
                                        try {
                                            dao.upsert(t.toLocal())
                                        } catch (e: Exception) {
                                        }
                                    }
                                }
                            }
                            override fun onFailure(call: Call<List<Task>>, t: Throwable) {
                                Log.e("Sync", "Falha rede", t)
                            }
                        })
                }
            } catch (e: Exception) {
                Log.e("Sync", "Exceção sync", e)
            }
        }
    }

    private fun TaskLocal.toApi(): Task = Task(
        id = id,
        userId = userId,
        title = title,
        description = description,
        day = day,
        daytime = daytime,
        notify = notify,
        recurring = recurring,
        updatedAt = updatedAt,
        completedAt = completedAt,
        deleted = deleted
    )

    private fun Task.toLocal(): TaskLocal = TaskLocal(
        id = id,
        userId = userId,
        title = title,
        description = description,
        day = day,
        daytime = daytime,
        notify = notify,
        recurring = recurring,
        updatedAt = updatedAt,
        completedAt = completedAt,
        deleted = deleted
    )

    fun alternarTela(fragment: Fragment) {
        supportFragmentManager.beginTransaction()
            .replace(binding.paginasFragment.id, fragment)
            .commit()
    }

    fun sair(telaAtual: Int) {
        MaterialAlertDialogBuilder(this)
            .setMessage("Deseja sair? Todos os alarmes serão desativados!")
            .setPositiveButton("Sim") { _, _ ->
                PrefsUtils.clearUserId(applicationContext)
                CacheUtils.limparCache(applicationContext)
                startActivity(Intent(this, MainActivity::class.java))
                finish()
            }
            .setNegativeButton("Cancelar") { dialog, _ ->
                dialog.dismiss()
                binding.bottomNavigation.selectedItemId = telaAtual
            }
            .show()
    }
}

package com.dev.rotinassim

import android.content.Intent
import android.os.Bundle
import android.util.Log
import androidx.activity.enableEdgeToEdge
import androidx.appcompat.app.AppCompatActivity
import androidx.core.view.ViewCompat
import androidx.core.view.WindowInsetsCompat
import androidx.fragment.app.Fragment
import androidx.lifecycle.lifecycleScope
import com.dev.rotinassim.api.RetrofitInstance
import com.dev.rotinassim.api.models.Task
import com.dev.rotinassim.databinding.ActivityPaginaPrincipalBinding
import com.dev.rotinassim.notifications.TaskAlarme
import com.dev.rotinassim.room.DatabaseRoom
import com.dev.rotinassim.room.entities.TaskLocal
import com.dev.rotinassim.utils.CacheUtils
import com.dev.rotinassim.utils.PrefsUtils
import com.google.android.material.dialog.MaterialAlertDialogBuilder
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import retrofit2.Call
import retrofit2.Callback
import retrofit2.Response

class PaginaPrincipal : AppCompatActivity() {

    lateinit var binding: ActivityPaginaPrincipalBinding
    lateinit var userId: String

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        binding = ActivityPaginaPrincipalBinding.inflate(layoutInflater)
        setContentView(binding.root)
        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main)) { v, insets ->
            val systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars())
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom)
            insets
        }
        userId = PrefsUtils.getUserId(applicationContext)
        sincronizarTarefas()
        var telaAtual = R.id.nav_tasks
        alternarTela(TarefasFragment())
        binding.bottomNavigation.setOnItemSelectedListener { item ->
            when (item.itemId) {
                R.id.nav_logoff -> { sair(telaAtual); false }
                R.id.nav_tasks -> {
                    if (telaAtual != R.id.nav_tasks) { alternarTela(TarefasFragment()); telaAtual = R.id.nav_tasks }
                    true
                }
                R.id.nav_settings -> {
                    if (telaAtual != R.id.nav_settings) { alternarTela(ConfiguracaoFragment()); telaAtual = R.id.nav_settings }
                    true
                }
                else -> false
            }
        }
    }

    fun sincronizarTarefas() {
        if (userId.isBlank()) { Log.d("Sync", "UserId vazio, cancelando sync"); return }
        lifecycleScope.launch {
            try {
                val db = DatabaseRoom.getDatabase(applicationContext)
                val dao = db.taskLocalDao()
                lifecycleScope.launch {
                    val tasksLocais = withContext(Dispatchers.IO) { dao.buscarTarefasPorUsuarioTodas(userId) }
                    val tasksApi = tasksLocais.map { it.toApi() }
                    RetrofitInstance.INSTANCE.sincronizar(userId, tasksApi)
                        .enqueue(object : Callback<List<Task>> {
                            override fun onResponse(call: Call<List<Task>>, response: Response<List<Task>>) {
                                if (!response.isSuccessful) {
                                    return
                                }
                                val lista = response.body().orEmpty()
                                lifecycleScope.launch{
                                    lista.forEach { t ->
                                        try {
                                            val local = t.toLocal()
                                            dao.upsert(local)
                                            // Agenda alarme para cada tarefa sincronizada
                                            TaskAlarme.schedule(applicationContext, local)
                                        } catch (e: Exception) {
                                        }
                                    }
                                    // avisa tela para recarregar
                                    supportFragmentManager.setFragmentResult("syncAtualizado", Bundle())
                                }
                            }
                            override fun onFailure(call: Call<List<Task>>, t: Throwable) {
                                Log.e("Sync", "Falha rede", t)
                            }
                        })
                }
            } catch (e: Exception) {
                Log.e("Sync", "Exceção sync", e)
            }
        }
    }

    private fun TaskLocal.toApi(): Task = Task(
        id = id,
        userId = userId,
        title = title,
        description = description,
        day = day,
        daytime = daytime,
        notify = notify,
        recurring = recurring,
        updatedAt = updatedAt,
        completedAt = completedAt,
        deleted = deleted
    )

    private fun Task.toLocal(): TaskLocal = TaskLocal(
        id = id,
        userId = userId,
        title = title,
        description = description,
        day = day,
        daytime = daytime,
        notify = notify,
        recurring = recurring,
        updatedAt = updatedAt,
        completedAt = completedAt,
        deleted = deleted
    )

    fun alternarTela(fragment: Fragment) {
        supportFragmentManager.beginTransaction()
            .replace(binding.paginasFragment.id, fragment)
            .commit()
    }

    fun sair(telaAtual: Int) {
        MaterialAlertDialogBuilder(this)
            .setMessage("Deseja sair? Todos os alarmes serão desativados!")
            .setPositiveButton("Sim") { _, _ ->
                PrefsUtils.clearUserId(applicationContext)
                CacheUtils.limparCache(applicationContext)
                startActivity(Intent(this, MainActivity::class.java))
                finish()
            }
            .setNegativeButton("Cancelar") { dialog, _ ->
                dialog.dismiss()
                binding.bottomNavigation.selectedItemId = telaAtual
            }
            .show()
    }
}

package com.dev.rotinassim

import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import androidx.fragment.app.Fragment
import androidx.lifecycle.lifecycleScope
import androidx.recyclerview.widget.LinearLayoutManager
import com.dev.rotinassim.adapters.TarefaAdapter
import com.dev.rotinassim.api.RetrofitInstance
import com.dev.rotinassim.api.models.Task
import com.dev.rotinassim.databinding.FragmentTarefasBinding
import com.dev.rotinassim.room.DatabaseRoom
import com.dev.rotinassim.room.entities.TaskLocal
import com.dev.rotinassim.utils.PrefsUtils
import kotlinx.coroutines.launch
import retrofit2.Call
import retrofit2.Callback
import retrofit2.Response
import java.util.Date

class TarefasFragment : Fragment() {

    private var _binding: FragmentTarefasBinding? = null
    private val binding get() = _binding!!

    private lateinit var proximasAdapter: TarefaAdapter
    private lateinit var recorrentesAdapter: TarefaAdapter

    override fun onCreateView(
        inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?
    ): View {
        _binding = FragmentTarefasBinding.inflate(inflater, container, false)
        configurarRecyclerViews()
        binding.botaoCriarTarefa.setOnClickListener {
            AdicionarTarefaFragment().show(parentFragmentManager, "")
        }

        parentFragmentManager.setFragmentResultListener("novaTarefa", viewLifecycleOwner) { _, _ ->
            carregarTarefas()
        }
        parentFragmentManager.setFragmentResultListener("syncAtualizado", viewLifecycleOwner) { _, _ ->
            carregarTarefas()
        }

        carregarTarefas()
        return binding.root
    }

    private fun configurarRecyclerViews() = with(binding) {
        proximasAdapter = TarefaAdapter(mutableListOf(), onConcluir = { concluirTarefa(it) }, onExcluir = { excluirTarefa(it) })
        recorrentesAdapter = TarefaAdapter(mutableListOf(), onConcluir = { concluirTarefa(it) }, onExcluir = { excluirTarefa(it) })

        listaProximas.layoutManager = LinearLayoutManager(requireContext())
        listaProximas.adapter = proximasAdapter

        listaRecorrente.layoutManager = LinearLayoutManager(requireContext())
        listaRecorrente.adapter = recorrentesAdapter
    }

    private fun carregarTarefas() {
        val userId = PrefsUtils.getUserId(requireContext())
        if (userId.isBlank()) return

        lifecycleScope.launch {
            try {
                val dao = DatabaseRoom.getDatabase(requireContext()).taskLocalDao()
                val todas = dao.buscarTarefasPorUsuario(userId)

                val recorrentes = todas.filter { val r = it.recurring; !r.isNullOrBlank() && r.contains('1') }
                val proximas = todas.filter { val r = it.recurring; r.isNullOrBlank() || !r.contains('1') }

                proximasAdapter.atualizarLista(proximas.sortedBy { it.day ?: Long.MAX_VALUE })
                recorrentesAdapter.atualizarLista(recorrentes.sortedBy { it.daytime })
            } catch (e: Exception) {
                e.printStackTrace()
            }
        }
    }

    private fun concluirTarefa(task: TaskLocal) {
        lifecycleScope.launch {
            val db = DatabaseRoom.getDatabase(requireContext())
            val dao = db.taskLocalDao()
            try {
                val agora = Date().time
                val atualizada = task.copy(completedAt = agora)
                dao.atualizarTarefa(atualizada)
                carregarTarefas()

                // Tenta sincronizar
                val taskApi = Task(
                    id = atualizada.id,
                    userId = atualizada.userId,
                    title = atualizada.title,
                    description = atualizada.description,
                    day = atualizada.day,
                    daytime = atualizada.daytime,
                    notify = atualizada.notify,
                    recurring = atualizada.recurring,
                    updatedAt = Date().time,
                    completedAt = atualizada.completedAt
                )
                RetrofitInstance.INSTANCE.atualizarTarefa(atualizada.id, taskApi).enqueue(object: Callback<Task> {
                    override fun onResponse(call: Call<Task>, response: Response<Task>) { }
                    override fun onFailure(call: Call<Task>, t: Throwable) { }
                })
            } catch (e: Exception) {
                e.printStackTrace()
            }
        }
    }

    private fun excluirTarefa(task: TaskLocal) {
        lifecycleScope.launch {
            val db = DatabaseRoom.getDatabase(requireContext())
            val dao = db.taskLocalDao()
            try {
                RetrofitInstance.INSTANCE.deletarTarefa(task.id).enqueue(object: Callback<Void> {
                    override fun onResponse(call: Call<Void>, response: Response<Void>) {}
                    override fun onFailure(call: Call<Void>, t: Throwable) {}
                })
                lifecycleScope.launch {
                    dao.atualizarTarefa(task.copy(deleted = true))
                    carregarTarefas()
                }

            } catch (e: Exception) {
                dao.atualizarTarefa(task.copy(deleted = true))
                carregarTarefas()
            }
        }
    }

    override fun onResume() {
        super.onResume()
        (activity as? PaginaPrincipal)?.sincronizarTarefas()
        carregarTarefas()
    }

    override fun onDestroyView() {
        super.onDestroyView()
        (activity as? PaginaPrincipal)?.sincronizarTarefas()
        _binding = null
    }
}

package com.dev.rotinassim

import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import androidx.fragment.app.Fragment
import androidx.lifecycle.lifecycleScope
import androidx.recyclerview.widget.LinearLayoutManager
import com.dev.rotinassim.adapters.TarefaAdapter
import com.dev.rotinassim.api.RetrofitInstance
import com.dev.rotinassim.api.models.Task
import com.dev.rotinassim.databinding.FragmentTarefasBinding
import com.dev.rotinassim.notifications.TaskAlarme
import com.dev.rotinassim.room.DatabaseRoom
import com.dev.rotinassim.room.entities.TaskLocal
import com.dev.rotinassim.utils.PrefsUtils
import kotlinx.coroutines.launch
import retrofit2.Call
import retrofit2.Callback
import retrofit2.Response
import java.util.Date

class TarefasFragment : Fragment() {

    private var _binding: FragmentTarefasBinding? = null
    private val binding get() = _binding!!

    private lateinit var proximasAdapter: TarefaAdapter
    private lateinit var recorrentesAdapter: TarefaAdapter

    override fun onCreateView(
        inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?
    ): View {
        _binding = FragmentTarefasBinding.inflate(inflater, container, false)
        configurarRecyclerViews()
        binding.botaoCriarTarefa.setOnClickListener {
            AdicionarTarefaFragment().show(parentFragmentManager, "")
        }

        parentFragmentManager.setFragmentResultListener("novaTarefa", viewLifecycleOwner) { _, _ ->
            carregarTarefas()
        }
        parentFragmentManager.setFragmentResultListener("syncAtualizado", viewLifecycleOwner) { _, _ ->
            carregarTarefas()
        }

        carregarTarefas()
        return binding.root
    }

    private fun configurarRecyclerViews() = with(binding) {
        proximasAdapter = TarefaAdapter(mutableListOf(), onConcluir = { concluirTarefa(it) }, onExcluir = { excluirTarefa(it) })
        recorrentesAdapter = TarefaAdapter(mutableListOf(), onConcluir = { concluirTarefa(it) }, onExcluir = { excluirTarefa(it) })

        listaProximas.layoutManager = LinearLayoutManager(requireContext())
        listaProximas.adapter = proximasAdapter

        listaRecorrente.layoutManager = LinearLayoutManager(requireContext())
        listaRecorrente.adapter = recorrentesAdapter
    }

    private fun carregarTarefas() {
        val userId = PrefsUtils.getUserId(requireContext())
        if (userId.isBlank()) return

        lifecycleScope.launch {
            try {
                val dao = DatabaseRoom.getDatabase(requireContext()).taskLocalDao()
                val todas = dao.buscarTarefasPorUsuario(userId)

                val recorrentes = todas.filter { val r = it.recurring; !r.isNullOrBlank() && r.contains('1') }
                val proximas = todas.filter { val r = it.recurring; r.isNullOrBlank() || !r.contains('1') }

                proximasAdapter.atualizarLista(proximas.sortedBy { it.day ?: Long.MAX_VALUE })
                recorrentesAdapter.atualizarLista(recorrentes.sortedBy { it.daytime })
            } catch (e: Exception) {
                e.printStackTrace()
            }
        }
    }

    private fun concluirTarefa(task: TaskLocal) {
        lifecycleScope.launch {
            val db = DatabaseRoom.getDatabase(requireContext())
            val dao = db.taskLocalDao()
            try {
                val agora = Date().time
                val atualizada = task.copy(completedAt = agora)
                dao.atualizarTarefa(atualizada)
                // Cancela alarme associado
                TaskAlarme.cancel(requireContext(), task.id)
                carregarTarefas()

                // Tenta sincronizar
                val taskApi = Task(
                    id = atualizada.id,
                    userId = atualizada.userId,
                    title = atualizada.title,
                    description = atualizada.description,
                    day = atualizada.day,
                    daytime = atualizada.daytime,
                    notify = atualizada.notify,
                    recurring = atualizada.recurring,
                    updatedAt = Date().time,
                    completedAt = atualizada.completedAt
                )
                RetrofitInstance.INSTANCE.atualizarTarefa(atualizada.id, taskApi).enqueue(object: Callback<Task> {
                    override fun onResponse(call: Call<Task>, response: Response<Task>) { }
                    override fun onFailure(call: Call<Task>, t: Throwable) { }
                })
            } catch (e: Exception) {
                e.printStackTrace()
            }
        }
    }

    private fun excluirTarefa(task: TaskLocal) {
        lifecycleScope.launch {
            val db = DatabaseRoom.getDatabase(requireContext())
            val dao = db.taskLocalDao()
            try {
                RetrofitInstance.INSTANCE.deletarTarefa(task.id).enqueue(object: Callback<Void> {
                    override fun onResponse(call: Call<Void>, response: Response<Void>) {}
                    override fun onFailure(call: Call<Void>, t: Throwable) {}
                })
                lifecycleScope.launch {
                    dao.atualizarTarefa(task.copy(deleted = true))
                    carregarTarefas()
                }

            } catch (e: Exception) {
                dao.atualizarTarefa(task.copy(deleted = true))
                carregarTarefas()
            }
        }
    }

    override fun onResume() {
        super.onResume()
        (activity as? PaginaPrincipal)?.sincronizarTarefas()
        carregarTarefas()
    }

    override fun onDestroyView() {
        super.onDestroyView()
        (activity as? PaginaPrincipal)?.sincronizarTarefas()
        _binding = null
    }
}
